changeSet.sql:
UPDATE clinlims.notebook_page SET page_order = 204 WHERE title = 'Sample Request & Retrieval' AND notebook_id IN ( SELECT DISTINCT np.notebook_id FROM clinlims.notebook_page np WHERE np.title = 'Storage Assignment' AND EXISTS ( SELECT 1 FROM clinlims.notebook_page np2 WHERE np2.notebook_id = np.notebook_id AND np2.title = 'Retention & Disposal' ) );
UPDATE clinlims.notebook_page SET page_order = 205 WHERE title = 'QC Inspection' AND notebook_id IN ( SELECT DISTINCT np.notebook_id FROM clinlims.notebook_page np WHERE np.title = 'Storage Assignment' AND EXISTS ( SELECT 1 FROM clinlims.notebook_page np2 WHERE np2.notebook_id = np.notebook_id AND np2.title = 'Retention & Disposal' ) );
UPDATE clinlims.notebook_page SET page_order = 206 WHERE title = 'Reporting & Audit' AND notebook_id IN ( SELECT DISTINCT np.notebook_id FROM clinlims.notebook_page np WHERE np.title = 'Storage Assignment' AND EXISTS ( SELECT 1 FROM clinlims.notebook_page np2 WHERE np2.notebook_id = np.notebook_id AND np2.title = 'Retention & Disposal' ) );
UPDATE clinlims.notebook_page SET page_order = 207 WHERE title = 'Retention & Disposal' AND notebook_id IN ( SELECT DISTINCT np.notebook_id FROM clinlims.notebook_page np WHERE np.title = 'Storage Assignment' AND EXISTS ( SELECT 1 FROM clinlims.notebook_page np2 WHERE np2.notebook_id = np.notebook_id AND np2.title = 'Retention & Disposal' ) );

UPDATE clinlims.notebook_page
SET page_order = 4
WHERE title = 'Sample Request & Retrieval' AND page_order = 204;

UPDATE clinlims.notebook_page
SET page_order = 5
WHERE title = 'QC Inspection' AND page_order = 205;

UPDATE clinlims.notebook_page
SET page_order = 6
WHERE title = 'Reporting & Audit' AND page_order = 206;

UPDATE clinlims.notebook_page
SET page_order = 7
WHERE title = 'Retention & Disposal' AND page_order = 207;

UPDATE clinlims.notebook_page SET content = REPLACE( content, '"nextPage": "Retention & Disposal"', '"nextPage": "Sample Request & Retrieval"' ) WHERE title = 'Ongoing Storage and Monitoring' AND content LIKE '%"nextPage": "Retention & Disposal"%';
UPDATE clinlims.notebook_page SET content = REPLACE( content, '"nextPage": "Retention & Disposal"', '"nextPage": "Reporting & Audit"' ) WHERE title = 'QC Inspection' AND content LIKE '%"nextPage": "Retention & Disposal"%';
UPDATE clinlims.notebook_page SET content = REPLACE( content, '"systemActions":', '"nextPage": "Retention & Disposal", "systemActions":' ) WHERE title = 'Reporting & Audit' AND content NOT LIKE '%nextPage%';
UPDATE clinlims.notebook_page SET content = REPLACE( content, '"nextPage": "Sample Request & Retrieval", ', '' ) WHERE title = 'Retention & Disposal' AND content LIKE '%"nextPage": "Sample Request & Retrieval"%';
UPDATE clinlims.notebook_page SET content = REPLACE( content, '"nextPage": "Reporting & Audit", ', '' ) WHERE title = 'Retention & Disposal' AND content LIKE '%"nextPage": "Reporting & Audit"%';

UPDATE clinlims.workflow_page_template
SET display_order = 204
WHERE workflow_category = 'BIOREPOSITORY' AND name = 'Sample Request & Retrieval';

UPDATE clinlims.workflow_page_template
SET display_order = 205
WHERE workflow_category = 'BIOREPOSITORY' AND name = 'QC Inspection';

UPDATE clinlims.workflow_page_template
SET display_order = 206
WHERE workflow_category = 'BIOREPOSITORY' AND name = 'Reporting & Audit';

UPDATE clinlims.workflow_page_template
SET display_order = 207
WHERE workflow_category = 'BIOREPOSITORY' AND name = 'Retention & Disposal';

UPDATE clinlims.workflow_page_template
SET display_order = 4
WHERE workflow_category = 'BIOREPOSITORY' AND display_order = 204;

UPDATE clinlims.workflow_page_template
SET display_order = 5
WHERE workflow_category = 'BIOREPOSITORY' AND display_order = 205;

UPDATE clinlims.workflow_page_template
SET display_order = 6
WHERE workflow_category = 'BIOREPOSITORY' AND display_order = 206;

UPDATE clinlims.workflow_page_template
SET display_order = 7
WHERE workflow_category = 'BIOREPOSITORY' AND display_order = 207;
